import os
import glob
from PIL import Image, ImageDraw

os.makedirs("previews", exist_ok=True)

# Convert all PPM files generated by the C++ test_native_render engine to PNG
ppm_files = glob.glob("previews/*.ppm")
png_map = {}

for ppm_path in sorted(ppm_files):
    png_path = os.path.splitext(ppm_path)[0] + ".png"
    with Image.open(ppm_path) as img:
        img.save(png_path)
        png_map[png_path] = img.copy()
        print(f"Converted native C++ output {ppm_path} -> {png_path}")

# Build VISUAL_COMPARISON.png 12-tile grid from native C++ outputs
cols, rows = 4, 3
tile_w, tile_h = 320, 240
grid_img = Image.new("RGB", (cols * tile_w, rows * tile_h), color=(20, 20, 20))

labels = [
    ("Original Footage", "previews/original.png"),
    ("Camera: Fxc6", "previews/camera_fxc6.png"),
    ("Camera: Gen 7", "previews/camera_gen7.png"),
    ("Camera: JVC GR-C7U", "previews/camera_jvc_c7u.png"),
    ("VHS SP Mode", "previews/vhs_sp_mode.png"),
    ("VHS LP Mode", "previews/vhs_lp_mode.png"),
    ("Bad Signal Glitch", "previews/bad_signal_glitch.png"),
    ("CRT TV Trinitron", "previews/crt_tv_trinitron.png"),
    ("Organic Grain", "previews/grain_color.png"),
    ("Dates & Text OSD", "previews/date_text_osd.png"),
    ("Full Master Suite", "previews/vhs_master_full_suite.png")
]

for idx, (label, png_path) in enumerate(labels):
    if os.path.exists(png_path):
        r_idx = idx // cols
        c_idx = idx % cols
        with Image.open(png_path) as img:
            resized = img.resize((tile_w, tile_h))
            draw = ImageDraw.Draw(resized)
            draw.rectangle([0, 0, tile_w, 24], fill=(0, 0, 0, 180))
            draw.text((8, 4), label, fill=(255, 255, 255))
            grid_img.paste(resized, (c_idx * tile_w, r_idx * tile_h))

grid_img.save("previews/VISUAL_COMPARISON.png")
print("Saved previews/VISUAL_COMPARISON.png grid from native C++ renders!")
